/// Letters: List the letters waiting for you.
@MainActor
public enum MailboxListAction {
    public static let id = "mailbox_list"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (MailboxListInput) async throws -> MailboxListOutput)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (MailboxListInput, Result<MailboxListOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: MailboxListInput) async throws -> MailboxListOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct MailboxListIntent: AppIntent {
    public static let title: LocalizedStringResource = "Letters"
    public static let description = IntentDescription("List the letters waiting for you.")

    public init() {}

    public init(_ input: MailboxListInput) {
        self.init()
    }

    public var input: MailboxListInput {
        MailboxListInput()
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<MailboxListOutput, any Error>
        do { result = .success(try await MailboxListAction.run(input)) } catch { result = .failure(error) }
        if let dialog = MailboxListAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

